"""Write plc/tia/LineIO_OB_DB.scl: the I/O DB, the instance DBs and OB30 (10 ms).

    python scripts/gen_tia_sources.py

The eight brake calls are generated so they cannot differ by a typo.  The FB parameters keep
their declared defaults, which equal the design values in captension.params (checked by
tests/test_physics.py::test_scl_defaults_match_design).
"""

from __future__ import annotations

from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]

HEAD = """// TIA Portal only. The Python translator handles FBs only and does not run this file.
// Generated by scripts/gen_tia_sources.py; edit that script, not this file.
// scripts/tia_build.ps1 generates the four FBs from ../FB_*.scl, then scripts/tia_ob30.ps1
// generates this file and turns "Cyclic_CapStrip" into a cyclic-interrupt OB30 at 10 ms.
// "LineIO" stands in for the line's I/O mapping (DOSSIER section 6, interface table).

DATA_BLOCK "LineIO"
{ S7_Optimized_Access := 'TRUE' }
VERSION : 0.1
NON_RETAIN
   VAR
      // IF-04 operator (HMI)
      StartReq : Bool;
      StopReq : Bool;
      JogReq : Bool;
      Ack : Bool;
      ClosedLoop : Bool := TRUE;
      Tset : Real := 15.0;   // N per cord at the template entrance (recipe)
      Trecipe : Real := 40.0;   // N strip tension at the winder (recipe)
      Taper : Real := 0.2;
      NewBobbin : Array[1..8] of Bool;
      NewSpool : Bool;
      DaqRelease : Bool;
      // IF-07 safety relay feedback
      EStopOk : Bool;
      // IF-01 tension sensors, IF-02 brake amplifiers, IF-03 spindle encoders
      Tension : Array[1..8] of Real;   // N
      TensionOk : Array[1..8] of Bool;
      BreakSwitch : Array[1..8] of Bool;
      Omega : Array[1..8] of Real;   // rad/s
      BrakeCurrent : Array[1..8] of Real;   // 0..1 of full scale, to the amplifiers
      Radius : Array[1..8] of Real;   // m, diameter estimate (HMI)
      Tvirtual : Array[1..8] of Real;   // N, model-based tension (HMI, plausibility)
      // IF-05 winder drive and strip load cell
      OmegaW : Real;   // rad/s
      StripT : Real;   // N
      StripTOk : Bool;
      WinderTorque : Real;   // N m, torque set point
      // IF-06 capstan drive and rubberising head
      SpeedRef : Real;   // m/s to the capstan drive
      DiePressure : Real;   // bar
      DieTemp : Real;   // degC
      // status
      LineMode : Int;
      BreakThread : Int;
      SlackFlag : Bool;
   END_VAR

BEGIN

END_DATA_BLOCK

"""


def idb(name: str, fb: str) -> str:
    return f"""DATA_BLOCK "{name}"
{{ S7_Optimized_Access := 'TRUE' }}
VERSION : 0.1
NON_RETAIN
"{fb}"

BEGIN

END_DATA_BLOCK

"""


def ob() -> str:
    s = ["""ORGANIZATION_BLOCK "Cyclic_CapStrip"
TITLE = Cap-strip line: unwind brakes, winder, supervisor and data collection, every 10 ms
{ S7_Optimized_Access := 'TRUE' }
VERSION : 0.1

BEGIN
	// modes, speed ramp, break and slack detection (uses the radii of the previous cycle)
	"iSUP"(StartReq := "LineIO".StartReq,
	       StopReq := "LineIO".StopReq,
	       JogReq := "LineIO".JogReq,
	       EStopOk := "LineIO".EStopOk,
	       Ack := "LineIO".Ack,
	       Tension := "LineIO".Tension,
	       TensionOk := "LineIO".TensionOk,
	       BreakSwitch := "LineIO".BreakSwitch,
	       Omega := "LineIO".Omega,
	       Radius := "LineIO".Radius,
	       ClosedLoop := "LineIO".ClosedLoop,
	       Tset := "LineIO".Tset);
	"LineIO".SpeedRef := "iSUP".SpeedRef;
	"LineIO".LineMode := "iSUP".LineMode;
	"LineIO".BreakThread := "iSUP".BreakThread;
	"LineIO".SlackFlag := "iSUP".SlackFlag;
"""]
    for i in range(1, 9):
        s.append(f"""
	"iBrake{i}"(BrakeMode := "iSUP".BrakeMode,
	          LineSpeed := "iSUP".SpeedRef,
	          LineAccel := "iSUP".AccelRef,
	          Omega := "LineIO".Omega[{i}],
	          Tmeas := "LineIO".Tension[{i}],
	          TmeasOk := "LineIO".TensionOk[{i}],
	          NewBobbin := "LineIO".NewBobbin[{i}],
	          Tset := "LineIO".Tset);
	"LineIO".BrakeCurrent[{i}] := "iBrake{i}".CurrentCmd;
	"LineIO".Radius[{i}] := "iBrake{i}".Radius;
	"LineIO".Tvirtual[{i}] := "iBrake{i}".Tvirtual;
""")
    s.append("""
	"iWinder"(WinderMode := "iSUP".WinderMode,
	          LineSpeed := "iSUP".SpeedRef,
	          LineAccel := "iSUP".AccelRef,
	          OmegaW := "LineIO".OmegaW,
	          StripT := "LineIO".StripT,
	          StripTOk := "LineIO".StripTOk,
	          NewSpool := "LineIO".NewSpool,
	          Trecipe := "LineIO".Trecipe,
	          Taper := "LineIO".Taper);
	"LineIO".WinderTorque := "iWinder".TorqueCmd;

	// topic task 1: data of brakes and winder, capture around a thread break
	"iDAQ"(Tension := "LineIO".Tension,
	       Current := "LineIO".BrakeCurrent,
	       Radius := "LineIO".Radius,
	       StripTension := "LineIO".StripT,
	       WinderTorque := "LineIO".WinderTorque,
	       LineSpeed := "iSUP".SpeedRef,
	       LineMode := "iSUP".LineMode,
	       DiePressure := "LineIO".DiePressure,
	       DieTemp := "LineIO".DieTemp,
	       Trigger := "iSUP".Trigger,
	       TriggerThread := "iSUP".BreakThread,
	       SlackFlag := "iSUP".SlackFlag,
	       Release := "LineIO".DaqRelease,
	       Tset := "LineIO".Tset);
END_ORGANIZATION_BLOCK
""")
    return "".join(s)


def main() -> None:
    txt = HEAD + idb("iSUP", "FB_LineSupervisor")
    for i in range(1, 9):
        txt += idb(f"iBrake{i}", "FB_ThreadBrake")
    txt += idb("iWinder", "FB_WinderTension") + idb("iDAQ", "FB_DataCollect") + ob()
    out = ROOT / "plc" / "tia" / "LineIO_OB_DB.scl"
    out.write_text(txt, encoding="utf-8", newline="\n")
    print(f"wrote {out}")


if __name__ == "__main__":
    main()
